  ok('idempotent', (await raw(a.token, 'PUT', `${mg('one')}/${b.user.id}`, { kind: 'member' })).status === 204)
  const e1 = await entry(oneCat, b.user.id)
  ok('appointing keeps the entry\'s other bits', e1.allow === (SEND | MCH | MMSG | MTHR) && e1.deny === ATTACH, JSON.stringify(e1))
  ok('listed', (await call(c.token, 'GET', mg('one'))).members.map((x) => x.id).join() === b.user.id)
  ok('listed with a display name', typeof (await call(c.token, 'GET', mg('one'))).members[0].display_name === 'string')
  ok('owner appoints a role', (await raw(a.token, 'PUT', `${mg('one')}/${helpers.id}`, { kind: 'role' })).status === 204 && (await call(c.token, 'GET', mg('one'))).roles[0].id === helpers.id)
